import{_ as d,C as i,o as l,c as o,aj as r,E as n,j as u}from"./chunks/framework.gl7gIbln.js";const h="/agentbook/diagrams/agenten-system-bausteine.png",w=JSON.parse('{"title":"Das persönliche Agenten-System","description":"","frontmatter":{"title":"Das persönliche Agenten-System"},"headers":[],"relativePath":"kapitel/04-persoenliches-agenten-system.md","filePath":"kapitel/04-persoenliches-agenten-system.md"}'),g={name:"kapitel/04-persoenliches-agenten-system.md"};function c(m,e,b,f,p,k){const t=i("Quiz"),s=i("Checklist"),a=i("FeedbackForm");return l(),o("div",null,[e[0]||(e[0]=r('<h1 id="kapitel-4-das-personliche-agenten-system" tabindex="-1">Kapitel 4: Das persönliche Agenten-System <a class="header-anchor" href="#kapitel-4-das-personliche-agenten-system" aria-label="Permalink to &quot;Kapitel 4: Das persönliche Agenten-System&quot;">​</a></h1><h2 id="rollen-regeln-speicher-und-routinen" tabindex="-1">Rollen, Regeln, Speicher und Routinen <a class="header-anchor" href="#rollen-regeln-speicher-und-routinen" aria-label="Permalink to &quot;Rollen, Regeln, Speicher und Routinen&quot;">​</a></h2><p>Sie öffnen Claude Code an einem Montagmorgen. Der Agent kennt Ihre Arbeitsweise, weiß welche Projekte gerade laufen, erinnert sich an Ihre Stilpräferenzen, kennt die Kunden, für die Sie arbeiten, und weiß, was letzte Woche noch offen geblieben ist. Sie müssen nichts erklären. Sie können sofort mit der Aufgabe beginnen.</p><p>Das ist kein Zufall. Das ist das Ergebnis einer bewussten Entscheidung, wie Sie Ihren Agenten einrichten. Ein Agent, dem Sie nie sagen, wer Sie sind und wie Sie arbeiten, ist ein Agent, dem Sie immer wieder alles von vorne erklären müssen. Ein Agent, der in einem sorgfältig aufgebauten Kontext arbeitet, wird schnell zu einem echten Begleiter der eigenen Arbeit.</p><p>Dieses Kapitel zeigt Ihnen, wie Sie aus einzelnen Prompts und Werkzeugkonfigurationen ein zusammenhängendes, persönliches Agenten-System aufbauen. Das kostet am Anfang etwas Zeit. Aber es ist die Investition, die jede spätere Arbeit effizienter macht.</p><h2 id="was-ein-personliches-agenten-system-ist" tabindex="-1">Was ein persönliches Agenten-System ist <a class="header-anchor" href="#was-ein-personliches-agenten-system-ist" aria-label="Permalink to &quot;Was ein persönliches Agenten-System ist&quot;">​</a></h2><p>Ein persönliches Agenten-System ist kein einzelnes Werkzeug und kein einzelner Prompt. Es ist die Gesamtheit aus Rollen, die Sie Ihren Agenten geben, Regeln, nach denen sie arbeiten, Speicher, in dem sie relevante Informationen über Sitzungen hinaus festhalten, und Routinen, die regelmäßig wiederkehrende Aufgaben automatisch anstoßen.</p><p>Stellen Sie sich das wie ein kleines Büro vor. Es gibt bestimmte Aufgabenbereiche, für die Sie Zuständigkeiten vergeben. Es gibt Arbeitsregeln, die für alle gelten. Es gibt Ablagesysteme, in denen Wissen gesammelt wird. Und es gibt Abläufe, die jede Woche nach dem gleichen Schema durchgeführt werden.</p><p>Das Ziel ist nicht, möglichst viel zu automatisieren. Das Ziel ist, ein System aufzubauen, das Ihnen jede Woche spürbar Zeit spart, das zuverlässig und nachvollziehbar arbeitet und das sich mit Ihrer Arbeit weiterentwickelt.</p><p><img src="'+h+'" alt="Die fünf Bausteine des persönlichen Agenten-Systems"></p><p>Die folgenden Abschnitte gehen diese fünf Bausteine von unten nach oben durch: zuerst das Fundament aus Kontext und Speicher, dann Rollen und Subagenten, Skills, Hooks und Berechtigungen und schließlich die Routinen, die alles automatisch anstoßen.</p><h2 id="rollen-agenten-mit-klaren-zustandigkeiten" tabindex="-1">Rollen: Agenten mit klaren Zuständigkeiten <a class="header-anchor" href="#rollen-agenten-mit-klaren-zustandigkeiten" aria-label="Permalink to &quot;Rollen: Agenten mit klaren Zuständigkeiten&quot;">​</a></h2><p>Der erste Schritt beim Aufbau eines persönlichen Agenten-Systems ist die Definition von Rollen. Eine Rolle beschreibt, für welche Art von Aufgaben ein Agent zuständig ist, welchen Kontext er dafür braucht, welche Werkzeuge er nutzen darf und wie er Ergebnisse präsentieren soll.</p><p>Warum Rollen? Weil ein Agent, dem Sie sagen &quot;Sie sind mein Recherche-Assistent, der belastbare Zusammenfassungen mit Quellenangaben liefert und Unsicherheiten markiert&quot;, konsequenter und vorhersehbarer arbeitet als ein Agent, dem Sie jedes Mal eine neue Aufgabe ohne Kontext geben.</p><p>Für Selbständige sind einige Rollen besonders nützlich.</p><p>Der Recherche-Assistent ist zuständig für Marktanalysen, Wettbewerbsrecherchen, Quellenprüfungen und Themenaufbereitungen. Er liefert immer ein Kurzfazit, belegbare Fakten, Quellenangaben und eine explizite Liste von Unsicherheiten.</p><p>Der Schreib-Assistent ist zuständig für Textentwürfe, Überarbeitungen, Formatierungen und Stilanpassungen. Er kennt Ihren Schreibstil, Ihre bevorzugte Satzlänge, Ihre Formulierungsregeln und Ihre Zielgruppen. Er macht Vorschläge, entscheidet aber nie selbst über Veröffentlichungen.</p><p>Der Projektassistent ist zuständig für das Begleiten laufender Projekte: Aufgabenlisten prüfen, Stände zusammenfassen, nächste Schritte vorschlagen, Blockaden markieren. Er kennt die Projekte, ihre Zeitrahmen und ihre Prioritäten.</p><p>Der Kommunikationsassistent ist zuständig für E-Mail-Entwürfe, Follow-up-Nachrichten und Angebotsvorbereitung. Er formuliert, liefert aber immer Entwürfe zur menschlichen Freigabe.</p><p>Jede dieser Rollen kann in einem einzigen Agenten oder in mehreren Agenten abgebildet werden. Die Entscheidung hängt davon ab, welche Werkzeuge für welche Rollen nötig sind und wie klar die Aufgabenbereiche voneinander getrennt bleiben sollen.</p><h2 id="kontextdateien-das-gedachtnis-das-sie-schreiben" tabindex="-1">Kontextdateien: Das Gedächtnis, das Sie schreiben <a class="header-anchor" href="#kontextdateien-das-gedachtnis-das-sie-schreiben" aria-label="Permalink to &quot;Kontextdateien: Das Gedächtnis, das Sie schreiben&quot;">​</a></h2><p>Jede Claude-Code-Sitzung beginnt ohne Erinnerung an vorherige Gespräche. Was sich über Sitzungen hinaus erhalten kann, kommt aus zwei Quellen: Dateien, die Sie selbst pflegen, und Auto-Memory, das Claude Code beim Arbeiten automatisch anlegt.</p><p>Das wichtigste Element ist die CLAUDE.md-Datei. Die offizielle Dokumentation beschreibt sie so: Behandeln Sie CLAUDE.md als den Ort, an dem Sie aufschreiben, was Sie sonst erneut erklären würden. Das trifft es präzise. Alles, was Sie einem neuen Mitarbeiter am ersten Tag mitteilen würden, gehört in diese Datei.</p><p>Konkret enthält eine gut gepflegte CLAUDE.md für Selbständige typischerweise folgendes: eine kurze Beschreibung der eigenen Tätigkeit und Zielgruppe, die wichtigsten laufenden Projekte mit Status, Stilregeln für Texte und Kommunikation, bevorzugte Ausgabeformate für verschiedene Aufgabentypen, wiederkehrende Aufgaben und ihre Erwartungsformate, sowie Dinge, die der Agent niemals tun soll, also explizite Grenzen.</p><p>Eine CLAUDE.md muss nicht lang sein. Eine gut strukturierte Datei mit einem bis zwei Seiten Text leistet mehr als ein zehn Seiten langes Dokument, das niemand aktuell hält. Die Dokumentation empfiehlt, spezifisch und prägnant zu schreiben, weil ein Agent spezifischen Anweisungen konsequenter folgt als allgemeinen.</p><p>CLAUDE.md-Dateien können auf mehreren Ebenen vorhanden sein. Eine globale Datei enthält allgemeine Informationen über Sie und Ihre Arbeitsweise, die für alle Projekte gelten. Projektspezifische Dateien enthalten Informationen, die nur für ein bestimmtes Projekt relevant sind. Claude Code liest beide Ebenen und kombiniert sie automatisch.</p><p>Diese Ebenen folgen einer festen Rangordnung. Zuerst lädt Claude Code eine etwaige unternehmensweite Datei, dann Ihre persönliche Datei im Heimatverzeichnis unter <code>~/.claude/CLAUDE.md</code>, zuletzt die projektspezifische Datei im Arbeitsordner. Spezifischere Ebenen haben dabei Vorrang vor allgemeineren: Was im Projekt steht, überschreibt im Zweifel die persönliche Vorgabe. So pflegen Sie allgemeine Arbeitsregeln an genau einer Stelle und müssen sie nicht in jedem Projekt wiederholen.</p><p>Drei Befehle erleichtern die Pflege im Alltag. Mit <code>/init</code> legt Claude Code in einem neuen Projekt automatisch eine erste CLAUDE.md mit Grundgerüst an. Mit <code>/memory</code> öffnen Sie die Speicherdateien direkt zur Bearbeitung. Und wenn Sie während der Arbeit eine Eingabe mit dem Zeichen <code>#</code> beginnen, schlägt Claude Code vor, diese Notiz dauerhaft in die Erinnerung aufzunehmen, ohne dass Sie die Datei selbst öffnen müssen.</p><p>Für umfangreichere Setups lassen sich Anweisungen aufteilen, statt sie in eine lange Datei zu pressen. Sie können thematische Dateien unter <code>.claude/rules/</code> ablegen, jede für ein Thema, und sie über die Import-Syntax einbinden: Eine Zeile wie <code>@rules/stil.md</code> am Anfang der CLAUDE.md zieht den Inhalt der genannten Datei hinein. Importierte Dateien dürfen ihrerseits weitere Dateien importieren, bis zu einer Tiefe von fünf Stufen. So bleibt jede Datei kurz und einem Zweck gewidmet, und dieselbe Stilregel kann von mehreren Projekten geteilt werden, ohne sie zu kopieren.</p><p>Für Codex gibt es die entsprechende AGENTS.md-Datei, die exakt dieselbe Funktion erfüllt. Sie enthält Arbeitsregeln, Berechtigungen, Hooks und projektspezifische Anweisungen. Das AGENTS.md-Format ist in über 60.000 Open-Source-Projekten verbreitet und hat sich als offener Standard etabliert. In größeren Projekten mit vielen Unterordnern können verschachtelte AGENTS.md-Dateien in jedem Unterordner liegen, wobei der Agent immer die nächste vorhandene Datei im Verzeichnisbaum liest.</p><h2 id="auto-memory-das-gedachtnis-das-von-selbst-wachst" tabindex="-1">Auto-Memory: Das Gedächtnis, das von selbst wächst <a class="header-anchor" href="#auto-memory-das-gedachtnis-das-von-selbst-wachst" aria-label="Permalink to &quot;Auto-Memory: Das Gedächtnis, das von selbst wächst&quot;">​</a></h2><p>Neben den Dateien, die Sie selbst schreiben, hat Claude Code ein Auto-Memory-System. Wenn Sie während einer Sitzung sagen &quot;Denke daran, immer mit kurzen Sätzen zu schreiben&quot; oder wenn Sie eine Korrektur am Stil des Agenten vornehmen, kann Claude Code diese Information selbständig in eine Memory-Datei schreiben und beim nächsten Start wieder abrufen.</p><p>Claude Code speichert nicht nach jeder Sitzung automatisch alles. Es entscheidet selbst, welche Informationen für zukünftige Sitzungen nützlich sein könnten: Build-Befehle, Debugging-Erkenntnisse, Architekturentscheidungen, Stilvorlieben und Arbeitsgewohnheiten. Die ersten 200 Zeilen oder 25 Kilobyte der Memory-Datei werden bei Sitzungsstart geladen. Darüber hinausgehende Informationen werden in separate Themendateien ausgelagert.</p><p>Das ist ein mächtiges System, das aber regelmäßiger Pflege bedarf. Über Zeit kann Auto-Memory mit veralteten oder widersprüchlichen Einträgen volllaufen. Prüfen Sie die Memory-Dateien Ihres Agenten daher in regelmäßigen Abständen, entfernen Sie irrelevante Einträge und aktualisieren Sie veraltete Informationen. Die Memory-Dateien sind einfache Textdateien, die Sie jederzeit bearbeiten oder löschen können.</p><h2 id="hermes-memory-der-langlebige-personliche-kontext" tabindex="-1">Hermes-Memory: Der langlebige persönliche Kontext <a class="header-anchor" href="#hermes-memory-der-langlebige-personliche-kontext" aria-label="Permalink to &quot;Hermes-Memory: Der langlebige persönliche Kontext&quot;">​</a></h2><p>Hermes verfolgt beim Thema Gedächtnis einen anderen Ansatz. Statt einer einzigen Memory-Datei nutzt Hermes ein mehrstufiges Gedächtnissystem mit verschiedenen Ebenen.</p><p>Das kurzfristige Gedächtnis ist der aktuelle Sitzungskontext: Was wurde besprochen, welche Aufgaben wurden durchgeführt, welche Entscheidungen getroffen. Dieses Gedächtnis gilt nur für die laufende Sitzung.</p><p>Das langfristige Gedächtnis ist in MEMORY.md und USER.md gespeichert. MEMORY.md enthält Fakten über laufende Projekte, bevorzugte Arbeitsweisen und wiederkehrende Aufgaben. USER.md ist ein wachsendes Profil Ihrer Persönlichkeit, Kommunikationspräferenzen und Arbeitsstile. Hermes nutzt außerdem ein sogenanntes dialektisches Nutzermodell, das über Sitzungen hinweg ein immer genaueres Bild Ihrer Arbeitsweise entwickelt.</p><p>Das dritte Gedächtnissystem sind Skills. Sie werden im nächsten Abschnitt ausführlicher behandelt.</p><p>Was Hermes besonders macht, ist die Fähigkeit zur Volltextsuche über vergangene Sitzungen mit anschließender KI-Zusammenfassung. Sie können also nicht nur sagen &quot;Was haben wir letzten Monat über Projekt X besprochen?&quot;, sondern Hermes durchsucht seine eigene Sitzungsgeschichte und liefert eine kohärente Zusammenfassung. Das ist ein erheblicher Vorteil gegenüber Agenten, die jede Sitzung von null beginnen.</p><h2 id="skills-wiederverwendbare-fahigkeitsmuster" tabindex="-1">Skills: Wiederverwendbare Fähigkeitsmuster <a class="header-anchor" href="#skills-wiederverwendbare-fahigkeitsmuster" aria-label="Permalink to &quot;Skills: Wiederverwendbare Fähigkeitsmuster&quot;">​</a></h2><p>Skills sind ein Konzept, das sich in allen vier Agenten-Werkzeugen findet und das für Selbständige besonders wertvoll ist.</p><p>Ein Skill ist eine gespeicherte Arbeitsanweisung für eine bestimmte Art von Aufgabe. Statt bei jedem Recherche-Auftrag erneut zu schreiben, wie das Ergebnis strukturiert sein soll, speichern Sie dieses Wissen als Skill. Der Agent ruft den Skill ab, wenn er gebraucht wird, und arbeitet danach, ohne dass Sie die Anweisung jedes Mal wiederholen müssen.</p><p>Bei Claude Code werden Skills als eigene Dateien im Projektordner gespeichert und sind sofort verfügbar, sobald sie gespeichert werden, ohne dass die Sitzung neu gestartet werden muss. Die empfohlene Vorgehensweise beim Aufbau von Skills ist iterativ: Einen Skill für den eigenen Gebrauch entwickeln, im Projekt testen, nach zwei bis drei Iterationen verfeinern und dann als feste Ressource einbinden.</p><p>Technisch ist ein Skill eine Datei namens SKILL.md mit einem kurzen Kopf aus Name und Beschreibung sowie optionalen Hilfsdateien in Unterordnern wie <code>scripts</code>, <code>references</code> und <code>assets</code>. Entscheidend ist das Prinzip der schrittweisen Offenlegung: Der Agent liest bei jeder Nachricht nur die kurzen Beschreibungen aller verfügbaren Skills und lädt den vollständigen Inhalt eines Skills erst dann, wenn er tatsächlich gebraucht wird. Dadurch bleibt das Kontextfenster schlank, auch wenn Sie über die Zeit viele Skills ansammeln. Persönliche Skills liegen unter <code>~/.claude/skills/</code>, projektbezogene unter <code>.claude/skills/</code>; Änderungen wirken sofort, ohne Neustart der Sitzung.</p><p>Bei Hermes gehen Skills noch einen Schritt weiter. Wenn Hermes eine komplexe Aufgabe erfolgreich abgeschlossen hat, zum Beispiel die Strukturierung einer Wettbewerbsanalyse, kann er aus dieser Erfahrung selbständig einen Skill erstellen: eine gespeicherte Beschreibung der Schritte, Methoden und Entscheidungen, die zum Erfolg geführt haben. Beim nächsten ähnlichen Auftrag ruft Hermes diesen Skill ab und startet nicht von null. Skills in Hermes folgen dem offenen Standard von agentskills.io und sind damit portierbar und teilbar.</p><p>Für Selbständige sind besonders folgende Skills am Anfang nützlich. Ein Recherche-Skill enthält eine Anweisung, wie Recherchen strukturiert sein sollen: Kurzfazit, Fakten mit Quellen, Unsicherheiten markiert, Format definiert. Ein Meeting-Nachbereitungs-Skill enthält eine Anweisung, wie aus einer Mitschrift Aufgaben, Entscheidungen und Follow-up-Entwürfe extrahiert werden. Ein Text-Review-Skill enthält Anweisungen für Stilkorrekturen: Was soll geprüft werden, nach welchem Stilprofil, in welchem Ausgabeformat. Ein Backoffice-Skill enthält eine Anweisung, wie Belege und Dokumente geordnet und benannt werden sollen.</p><h2 id="subagenten-rollen-als-eigenstandige-helfer" tabindex="-1">Subagenten: Rollen als eigenständige Helfer <a class="header-anchor" href="#subagenten-rollen-als-eigenstandige-helfer" aria-label="Permalink to &quot;Subagenten: Rollen als eigenständige Helfer&quot;">​</a></h2><p>Die Rollen aus dem ersten Abschnitt lassen sich in Claude Code als echte Subagenten fest verankern. Ein Subagent ist ein spezialisierter Helfer mit eigenem Kontextfenster, eigenem Systemprompt, eigener Werkzeugfreigabe und eigener Modellwahl. Sie definieren ihn als Markdown-Datei mit einem kurzen YAML-Kopf, entweder projektbezogen unter <code>.claude/agents/</code> oder persönlich und projektübergreifend unter <code>~/.claude/agents/</code>. Der Befehl <code>/agents</code> führt Sie interaktiv durch das Anlegen.</p><p>Für Selbständige hat dieses Modell drei praktische Vorteile. Erstens das eigene Kontextfenster: Ein Recherche-Subagent kann eine umfangreiche Quellensichtung durchführen, ohne Ihren Hauptkontext mit Zwischenergebnissen zu überladen; zurück kommt nur das fertige Ergebnis. Zweitens die Werkzeugbeschränkung: Sie können einem Subagenten gezielt nur die Werkzeuge erlauben, die seine Rolle wirklich braucht, was unmittelbar an die Sicherheitsprinzipien aus Kapitel 3 anschließt. Drittens die Modellwahl: Einfache, häufige Aufgaben lassen sich an ein schnelleres, günstigeres Modell wie Haiku weiterreichen, während anspruchsvolle Arbeit beim stärkeren Modell bleibt. Das senkt die laufenden Kosten spürbar, ohne dass die Qualität dort leidet, wo sie zählt.</p><p>Auf Wunsch erhält ein persönlicher Subagent ein eigenes Gedächtnisverzeichnis unter <code>~/.claude/agent-memory/</code>, in dem er wiederkehrende Muster und Erkenntnisse über Sitzungen hinweg sammelt. So wird aus einer einmal beschriebenen Rolle ein dauerhaft verfügbarer, spezialisierter Mitarbeiter, den Sie in jedem Projekt abrufen können.</p><h2 id="hooks-regeln-die-immer-gelten" tabindex="-1">Hooks: Regeln, die immer gelten <a class="header-anchor" href="#hooks-regeln-die-immer-gelten" aria-label="Permalink to &quot;Hooks: Regeln, die immer gelten&quot;">​</a></h2><p>Hooks sind automatische Aktionen, die bei bestimmten Ereignissen ausgelöst werden. Sie funktionieren unabhängig davon, was der Agent im Moment plant. Während eine CLAUDE.md-Anweisung den Agenten lenkt, aber nicht erzwingt, setzt ein Hook eine Regel deterministisch durch.</p><p>Claude Code unterstützt verschiedene Hook-Typen. Ein PreToolUse-Hook wird ausgelöst, bevor ein Werkzeug aufgerufen wird, und kann die Aktion prüfen oder blockieren. Ein Stop-Hook wird ausgelöst, wenn Claude Code eine Antwort fertiggestellt hat, und kann die Ausgabe noch einmal prüfen. Ein UserPromptSubmit-Hook wird ausgelöst, bevor Ihr Prompt das Modell erreicht, und kann zusätzliche Anweisungen hinzufügen.</p><p>Insgesamt kennt Claude Code über ein Dutzend solcher Auslösepunkte im Arbeitsablauf. Ein PreToolUse-Hook kann eine Aktion ausdrücklich erlauben, verweigern oder zur Rückfrage an Sie eskalieren. Konfiguriert werden Hooks in der Datei <code>settings.json</code>, entweder projektbezogen unter <code>.claude/settings.json</code> oder persönlich unter <code>~/.claude/settings.json</code>, wobei die Projektebene im Konfliktfall Vorrang hat. Eng damit verbunden ist der Berechtigungsbereich derselben Datei: Über Erlaubnis- und Verbotslisten legen Sie fest, welche Befehle ein Agent ohne Rückfrage ausführen darf und welche grundsätzlich blockiert sind. Genau diese Kombination aus Hooks und Berechtigungen ist das technische Rückgrat des datensicheren Arbeitens aus Kapitel 3: Sie verlassen sich nicht auf das Wohlverhalten des Modells, sondern setzen Grenzen, die unabhängig von seiner jeweiligen Absicht gelten.</p><p>Für Selbständige sind Hooks am nützlichsten als Sicherheitsnetz: Ein Hook, der jede E-Mail-Sendeanfrage automatisch blockiert und zur menschlichen Bestätigung weiterleitet. Ein Hook, der nach jeder Sitzung automatisch eine Zusammenfassung in eine Protokolldatei schreibt. Ein Hook, der vor jeder Dateiänderung den Dateinamen und den geplanten Inhalt der Änderung protokolliert.</p><p>Die Empfehlung aus der Praxis lautet: Hooks sollten am Ende der Arbeit laufen, nicht während jedes einzelnen Schritts. Zu viele Unterbrechungen während der Arbeit machen die Arbeit mit dem Agenten mühsam. Ein finaler Prüf-Hook, der nach Abschluss einer Aufgabe das Gesamtergebnis bewertet, ist produktiver als ein Hook, der nach jedem Einzelschritt unterbricht.</p><h2 id="routinen-wiederkehrende-aufgaben-automatisch-anstoßen" tabindex="-1">Routinen: Wiederkehrende Aufgaben automatisch anstoßen <a class="header-anchor" href="#routinen-wiederkehrende-aufgaben-automatisch-anstoßen" aria-label="Permalink to &quot;Routinen: Wiederkehrende Aufgaben automatisch anstoßen&quot;">​</a></h2><p>Der letzte Baustein des persönlichen Agenten-Systems sind Routinen, also zeitgesteuerte oder situationsgesteuerte Abläufe, die regelmäßig ausgeführt werden.</p><p>Hermes hat dafür ein integriertes Cron-System, das Aufgaben zu bestimmten Zeiten oder nach bestimmten Ereignissen automatisch startet. Ein Hermes-Agent kann zum Beispiel jeden Montag um acht Uhr morgens automatisch die Wochenplanung anstoßen: Kalenderereignisse der Woche prüfen, offene Aufgaben aus der letzten Woche zusammenfassen, Prioritäten für heute vorschlagen.</p><p>Claude Code und Codex unterstützen Routinen über Automations-Konfigurationen, die in den jeweiligen Einstellungsdateien definiert werden. In Codex werden wiederkehrende Aufgaben als Automations beschrieben und können als regelmäßige Prozesse eingerichtet werden.</p><p>In der Codex-App genügen für eine Automation vier Angaben: Name, Projekt, Anweisung und Zeitplan. Codex führt die Aufgabe dann im Hintergrund in einem separaten Arbeitszweig aus und legt das Ergebnis in einer Prüf-Warteschlange ab, die Sie später in Ruhe durchsehen. Der separate Arbeitszweig sorgt dafür, dass automatische Änderungen Ihre laufende Arbeit nicht überschreiben. Wichtig bei lokal laufenden Automationen: Der Rechner muss eingeschaltet und Codex gestartet sein, damit die geplante Aufgabe zur vorgesehenen Zeit ausgeführt wird. Cloud-gestützte Routinen wie bei Hermes haben diese Einschränkung nicht, laufen dafür aber außerhalb Ihrer lokalen Umgebung.</p><p>Besonders nützliche Routinen für Selbständige sind:</p><p>Das tägliche Morgenbriefing: Kalender des Tages, drei wichtigste offene Aufgaben, dringende E-Mails, Fristen der nächsten 48 Stunden. Diese Routine dauert für den Agenten zwei bis drei Minuten, spart Ihnen aber die Zeit, alle diese Informationen selbst zusammenzusuchen.</p><p>Die wöchentliche Rückschau: Was wurde abgeschlossen? Was ist offen geblieben? Was wurde gelernt? Was muss die nächste Woche passieren?</p><p>Der Freitagsabschluss: Belege der Woche prüfen, Dateinamen vereinheitlichen, offene Rechnungen markieren, Aufgabenliste für die nächste Woche vorbereiten.</p><p>Das monatliche Reporting: Einnahmen, Ausgaben, abgeschlossene Projekte, offene Posten, drei wichtigste Erkenntnisse des Monats.</p><p>Jede dieser Routinen muss einmalig konfiguriert werden. Danach läuft sie automatisch, und Sie bekommen ein strukturiertes Briefing, das Sie prüfen, korrigieren und als Entscheidungsgrundlage nutzen.</p><h2 id="der-schrittweise-aufbau-eine-empfehlung-fur-die-praxis" tabindex="-1">Der schrittweise Aufbau: Eine Empfehlung für die Praxis <a class="header-anchor" href="#der-schrittweise-aufbau-eine-empfehlung-fur-die-praxis" aria-label="Permalink to &quot;Der schrittweise Aufbau: Eine Empfehlung für die Praxis&quot;">​</a></h2><p>Der häufigste Fehler beim Aufbau eines persönlichen Agenten-Systems ist der Versuch, alles auf einmal einzurichten. Das Ergebnis ist ein System, das zu komplex ist, das Sie nicht wirklich verstehen und das beim ersten Problem zusammenbricht.</p><p>Die bessere Strategie ist schrittweise. In der ersten Woche legen Sie eine einfache CLAUDE.md oder AGENTS.md an mit den wichtigsten Informationen über Sie und Ihre Arbeit. Dann nehmen Sie eine Aufgabe, die Sie regelmäßig erledigen, und richten dafür einen ersten Skill ein. Sie nutzen diesen Skill eine Woche lang täglich und prüfen dabei: Folgt der Agent der Anweisung? Fehlt ihm Kontext? Was muss verbessert werden?</p><p>In der zweiten Woche fügen Sie eine erste Routine hinzu. Das Morgenbriefing ist ein guter Einstieg, weil es täglich läuft, schnell zu konfigurieren ist und sofortige Rückmeldung darüber gibt, ob der Kontext stimmt.</p><p>In der dritten Woche richten Sie einen oder zwei Hooks ein, die als Sicherheitsnetz dienen. Ein einfacher Hook, der nach jeder Sitzung eine kurze Protokollnotiz schreibt, ist ein guter Anfang.</p><p>Ab der vierten Woche können Sie das System schrittweise erweitern: neue Skills für neue Aufgabentypen, neue Routinen für wiederkehrende Abläufe, neue Kontextinformationen für neue Projekte.</p><p>Das System muss nicht fertig sein. Es muss nützlich sein. Und es wird mit jeder Woche nützlicher, wenn Sie es konsequent pflegen und weiterentwickeln.</p><h2 id="ein-konkretes-beispiel-das-projektordner-setup" tabindex="-1">Ein konkretes Beispiel: Das Projektordner-Setup <a class="header-anchor" href="#ein-konkretes-beispiel-das-projektordner-setup" aria-label="Permalink to &quot;Ein konkretes Beispiel: Das Projektordner-Setup&quot;">​</a></h2><p>Stellen Sie sich vor, Sie betreuen drei verschiedene Kundenprojekte gleichzeitig. Für jedes Projekt gibt es einen eigenen Ordner auf Ihrem Computer. In jedem Ordner liegt eine CLAUDE.md oder AGENTS.md, die folgendes enthält: eine kurze Beschreibung des Projekts und des Kunden, den aktuellen Stand, die wichtigsten nächsten Schritte, die wichtigsten Stilregeln für diesen Kunden sowie Dinge, die bei diesem Projekt besonders beachtet werden müssen.</p><p>Wenn Sie Claude Code in einem dieser Ordner starten, liest der Agent zuerst die globale CLAUDE.md mit allgemeinen Informationen über Sie, dann die projektspezifische Datei mit dem Projektkontext. Ohne einen einzigen Satz erklären zu müssen, ist der Agent im richtigen Kontext für die Arbeit an diesem Projekt.</p><p>Das ist das Kernversprechen eines gut aufgebauten persönlichen Agenten-Systems: Nicht mehr Zeit damit zu verbringen, dem Agenten zu erklären, wer Sie sind und was Sie brauchen, sondern sofort mit der eigentlichen Aufgabe beginnen zu können.</p><h2 id="interaktiv-selbsttest-und-aufbau-checkliste" tabindex="-1">Interaktiv: Selbsttest und Aufbau-Checkliste <a class="header-anchor" href="#interaktiv-selbsttest-und-aufbau-checkliste" aria-label="Permalink to &quot;Interaktiv: Selbsttest und Aufbau-Checkliste&quot;">​</a></h2><p>Prüfen Sie kurz, ob die wichtigsten Bausteine sitzen:</p>',81)),n(t,{question:"Welche CLAUDE.md-Ebene hat im Konfliktfall Vorrang?",options:["Die unternehmensweite Datei","Die persönliche Datei im Heimatverzeichnis","Die projektspezifische Datei im Arbeitsordner"],answer:2,hint:"Spezifischer schlägt allgemeiner."}),n(t,{question:"Wofür ist ein Subagent mit eigener Werkzeugfreigabe besonders nützlich?",options:["Um den Hauptkontext zu entlasten und Rechte gezielt zu begrenzen","Um Texte schneller zu drucken","Um die CLAUDE.md automatisch zu löschen"],answer:0,hint:"Eigenes Kontextfenster, begrenzte Werkzeuge, passende Modellwahl."}),e[1]||(e[1]=u("p",null,"Und hier Ihr Aufbauplan zum Abhaken – der Fortschritt bleibt in diesem Browser gespeichert:",-1)),n(s,{"storage-key":"ch4-aufbau",items:["Woche 1: CLAUDE.md oder AGENTS.md mit den wichtigsten Eckdaten anlegen","Woche 1: ersten Skill für eine wiederkehrende Aufgabe einrichten und täglich nutzen","Woche 2: erste Routine ergänzen, zum Beispiel ein Morgenbriefing","Woche 3: einen oder zwei Hooks als Sicherheitsnetz einrichten","Ab Woche 4: System schrittweise um Subagenten, Skills und Routinen erweitern"]}),e[2]||(e[2]=r('<h2 id="quellen" tabindex="-1">Quellen <a class="header-anchor" href="#quellen" aria-label="Permalink to &quot;Quellen&quot;">​</a></h2><ul><li>Anthropic: Claude Code – Memory und CLAUDE.md (<code>code.claude.com/docs/en/memory</code>)</li><li>Anthropic: Claude Code – Subagenten (<code>code.claude.com/docs/en/sub-agents</code>)</li><li>Anthropic: Claude Code – Hooks (<code>code.claude.com/docs/en/hooks</code>)</li><li>Anthropic: Agent Skills (<code>code.claude.com/docs/en/skills</code>)</li><li>OpenAI: Codex – Automations (<code>developers.openai.com/codex/app/automations</code>)</li></ul>',2)),n(a)])}const A=d(g,[["render",c]]);export{w as __pageData,A as default};
